/// log-drawer: API request
private struct LogDrawerExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var isPresented = PreviewMode.presented ? true : false

    /// The tone of an HTTP status: 2xx success, 3xx info, 4xx warning, 5xx danger.
    private func tone(_ status: Int) -> MonarchTone {
        switch status {
        case 500...: .danger
        case 400..<500: .warning
        case 300..<400: .info
        case 200..<300: .success
        default: .neutral
        }
    }

    var body: some View {
        MonarchButton("View request") { isPresented = true }
            .sheet(isPresented: $isPresented) {
                NavigationStack {
                    ScrollView {
                        VStack(alignment: .leading, spacing: theme.spacing.space4) {
                            Text("Request and response bodies are not stored.")
                                .monarchTextStyle(.body)
                                .foregroundStyle(theme.colors.textMuted)
                            LabeledContent("Operation") {
                                HStack(spacing: theme.spacing.space2) {
                                    MonarchMethodBadge("POST")
                                    Text("/v1/orders").monarchTextStyle(.code)
                                }
                            }
                            LabeledContent("Status") {
                                HStack(spacing: theme.spacing.space2) {
                                    MonarchStatusBadge(MonarchStatusDefinition(String(429), tone: tone(429)), size: .sm)
                                    Text("rate_limited").monarchTextStyle(.code)
                                }
                            }
                            LabeledContent("Request ID") {
                                HStack(spacing: theme.spacing.space1) {
                                    Text(verbatim: "req_7f3a2c90d1").monarchTextStyle(.code)
                                    MonarchCopyButton(value: "req_7f3a2c90d1", target: "request ID", variant: .ghost, isIconOnly: true)
                                }
                            }
                            LabeledContent("Time") {
                                Text(RelativeDateTimeFormatter().localizedString(for: Date().addingTimeInterval(-4.0 * 60), relativeTo: Date()))
                                    // A dotted underline marks the time that shows the exact moment on the web.
                                    .underline(pattern: .dot)
                            }
                            LabeledContent("Duration") {
                                Text("\(84) ms")
                            }
                            LabeledContent("Credential") {
                                Text("Reporting job")
                            }
                            LabeledContent("Origin") {
                                HStack(spacing: theme.spacing.space1) {
                                    Text(verbatim: "https://shop.example.com").monarchTextStyle(true ? .code : .body)
                                        .foregroundStyle(theme.colors.textDefault)
                                    MonarchCopyButton(value: "https://shop.example.com", target: "Origin", variant: .ghost, isIconOnly: true)
                                }
                            }
                            LabeledContent("Units") {
                                Text("1 request")
                            }
                        }
                        .labeledContentStyle(.monarch)
                        .padding(theme.spacing.space4)
                    }
                    .navigationTitle("Request details")
                    #if os(iOS)
                    .navigationBarTitleDisplayMode(.inline)
                    #endif
                    .toolbar {
                        ToolbarItem(placement: .confirmationAction) {
                            Button("Close") { isPresented = false }
                        }
                    }
                }
                .presentationDetents([.medium, .large])
            }
    }
}

